/**
 * Which files under `docs/` ship in the npm tarball, and how public pages
 * are produced.
 *
 * Hand-written handbook pages live in `site/content/docs`. Public package
 * pages under `docs/*.md` (except a short hand-kept stop-line list) and every
 * `docs/errors/OKM####.md` are generated by `generate` from those site pages
 * and from the error registry. Internal notes stay in git under `docs/`.
 *
 *   bun ./scripts/docs-pack.ts
 *   bun ./scripts/docs-pack.ts --write-ignore
 *   bun ./scripts/docs-pack.ts generate
 *   bun ./scripts/docs-pack.ts stamp
 *   bun ./scripts/docs-pack.ts restore
 */

import {
  cpSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative, sep } from "node:path";

import { pageExample } from "../src/tooling/errors/examples.js";
import { renderErrorPage } from "../src/tooling/errors/page.js";
import { ERROR_DOCS } from "../src/tooling/errors/registry.js";
import { writeCapabilityDocs } from "./docs-capabilities.js";
import { renderDocsIndex } from "./docs-index.js";
import {
  codesInText,
  mdxToPackBody,
  rewriteHandbookLinks,
  stripYamlFrontmatter,
} from "./docs-mdx.js";
import { exitOnProblems } from "./report.js";
import { repoRoot } from "./root.js";

/** Backup of public docs while `stamp` rewrites the packed copy. Untracked. */
export const PACK_BACKUP = ".okm-docs-pack";

/** `docs/.npmignore`, relative to the repository root. */
export const NPM_IGNORE = "docs/.npmignore";

/**
 * Public guides generated from one handbook MDX page, relative to `docs/`.
 *
 * Key is the packed filename. Value is the path under `site/content/docs`.
 */
export const SITE_DOC_SOURCES = {
  "adopt-existing.md": "migrations/adopt-existing-database.mdx",
  "api.md": "reference/package-exports.mdx",
  "backfill.md": "migrations/backfill.mdx",
  "compatibility.md": "reference/compatibility.mdx",
  "environments.md": "migrations/environments.mdx",
  "github-action.md": "reference/github-action.mdx",
  "migrate-check.md": "migrations/checks-and-lint.mdx",
  "migration-failure.md": "migrations/failures.mdx",
  "observer-events.md": "reference/observer-events.mdx",
  "production.md": "operate/production-checklist.mdx",
  "protection.md": "operate/protected-targets-and-roles.mdx",
  "roles.md": "operate/protected-targets-and-roles.mdx",
  "testing.md": "operate/testing.mdx",
  "threat-model.md": "concepts/the-safety-model.mdx",
  "topology.md": "operate/replicas-and-topology.mdx",
  "type-change.md": "reference/type-change.mdx",
  "warnings.md": "reference/warnings.mdx",
  "using-okmodel-safely.md": "operate/using-okmodel-safely.mdx",
} as const;

/**
 * Public pages that stay hand-kept because no single site page expresses the
 * executable fixture faithfully (stop line). Relative to `docs/`.
 */
export const HAND_KEPT_DOCS = ["guide.md", "quickstart.md"] as const;

/**
 * Public pages produced by a code generator rather than from MDX.
 * Relative to `docs/`.
 */
export const CODE_DOC_SOURCES = [
  "index.md",
  "capabilities.md",
  "extension-compatibility.md",
] as const;

/**
 * Deliberate removals from the previous public set. Content moved into a
 * site page that already feeds another packed file, or dropped as stale.
 */
export const REMOVED_PUBLIC_DOCS = [
  "linter.md",
  "provisioning.md",
  "example-app.md",
  "untrusted.md",
] as const;

/**
 * Public guides, relative to `docs/`.
 *
 * `docs/errors/OKM####.md` is public by pattern and is not listed here.
 */
export const PUBLIC_DOCS = [
  ...HAND_KEPT_DOCS,
  ...CODE_DOC_SOURCES,
  ...(Object.keys(SITE_DOC_SOURCES) as (keyof typeof SITE_DOC_SOURCES)[]),
].sort() as unknown as readonly string[];

/**
 * Repository notes that must not be packed, relative to `docs/`.
 *
 * `.npmignore` is the generated exclusion list. It is internal so the
 * classifier still sees it.
 */
export const INTERNAL_DOCS = [
  ".npmignore",
  "github.md",
  "m0-findings.md",
  "okmodel-api-design.md",
  "okmodel-decisions.md",
  "okmodel-execution-plan.md",
  "postgresjs-kill-storm.md",
  "postgresjs-kill-storm.mjs",
  "release.md",
  "size.md",
] as const;

const ERROR_PAGE = /^errors\/OKM\d{4}\.md$/;

/** Pack front-matter defaults when a site page does not list codes. */
const DOC_META: Readonly<
  Record<string, { readonly since: string; readonly dialects: readonly string[] }>
> = {
  "adopt-existing.md": { since: "0.9", dialects: ["postgres"] },
  "api.md": { since: "0.9", dialects: ["postgres"] },
  "backfill.md": { since: "0.9", dialects: ["postgres"] },
  "capabilities.md": { since: "0.10", dialects: ["postgres"] },
  "compatibility.md": { since: "0.9", dialects: ["postgres"] },
  "environments.md": { since: "0.9", dialects: ["postgres"] },
  "extension-compatibility.md": { since: "0.9", dialects: ["postgres"] },
  "github-action.md": { since: "0.9", dialects: ["postgres"] },
  "index.md": { since: "0.10", dialects: ["postgres"] },
  "migrate-check.md": { since: "0.9", dialects: ["postgres"] },
  "migration-failure.md": { since: "0.9", dialects: ["postgres"] },
  "observer-events.md": { since: "0.10", dialects: ["postgres"] },
  "production.md": { since: "0.9", dialects: ["postgres"] },
  "protection.md": { since: "0.9", dialects: ["postgres"] },
  "roles.md": { since: "0.10", dialects: ["postgres"] },
  "testing.md": { since: "0.9", dialects: ["postgres"] },
  "threat-model.md": { since: "0.10", dialects: ["postgres"] },
  "topology.md": { since: "0.9", dialects: ["postgres"] },
  "type-change.md": { since: "0.9", dialects: ["postgres"] },
  "warnings.md": { since: "0.10", dialects: ["postgres"] },
  "using-okmodel-safely.md": { since: "0.9", dialects: ["postgres"] },
};

/** One file under `docs/` and the decision recorded for it. */
export type DocClass = "public" | "internal";

/**
 * Release version with a `-next.N` suffix removed.
 *
 * @param version - `package.json` version
 * @returns The train version committed into front matter and the index title
 */
export function committedDocVersion(version: string): string {
  return version.replace(/-next\.\d+$/, "");
}

/**
 * Class of one path relative to `docs/`, or `undefined` when nobody decided.
 *
 * @param rel - Forward-slash path under `docs/`
 * @returns The recorded class
 */
export function docClass(rel: string): DocClass | undefined {
  if ((PUBLIC_DOCS as readonly string[]).includes(rel)) return "public";
  if ((INTERNAL_DOCS as readonly string[]).includes(rel)) return "internal";
  if (ERROR_PAGE.test(rel)) return "public";
  return undefined;
}

/**
 * Whether a public path is generated (not hand-kept).
 *
 * @param rel - Path under `docs/`
 */
export function isGeneratedPublicDoc(rel: string): boolean {
  if (ERROR_PAGE.test(rel)) return true;
  if ((HAND_KEPT_DOCS as readonly string[]).includes(rel)) return false;
  return (PUBLIC_DOCS as readonly string[]).includes(rel);
}

/**
 * Problems in the classification of `docs/`.
 *
 * Generated publics may be missing until `generate` runs. Hand-kept and
 * internal paths must exist. A new on-disk file must be classified.
 *
 * @param root - Repository root
 * @returns Problem lines
 */
export function classificationProblems(root: string): readonly string[] {
  const problems: string[] = [];
  const onDisk = new Set(docsFiles(root));
  const seen = new Set<string>();
  for (const rel of [...PUBLIC_DOCS, ...INTERNAL_DOCS]) {
    if (seen.has(rel)) problems.push(`docs-pack: ${rel} is listed twice`);
    seen.add(rel);
    if (!onDisk.has(rel) && !isGeneratedPublicDoc(rel)) {
      problems.push(`docs-pack: ${rel} is listed but missing`);
    }
  }
  for (const rel of [...onDisk].sort()) {
    if (docClass(rel) === undefined) problems.push(`docs-pack: ${rel} is not public or internal`);
  }
  for (const rel of PUBLIC_DOCS) {
    if ((INTERNAL_DOCS as readonly string[]).includes(rel)) {
      problems.push(`docs-pack: ${rel} is both public and internal`);
    }
  }
  for (const rel of REMOVED_PUBLIC_DOCS) {
    if (onDisk.has(rel) && docClass(rel) === undefined) {
      problems.push(`docs-pack: ${rel} was removed from PUBLIC_DOCS but is still on disk`);
    }
  }
  return problems;
}

/**
 * `.npmignore` body for `docs/`.
 *
 * @returns The file contents, ending in a newline
 */
export function npmIgnoreText(): string {
  const lines = INTERNAL_DOCS.filter((rel) => rel !== ".npmignore")
    .slice()
    .sort();
  return `# Generated by scripts/docs-pack.ts. Do not edit.\n${lines.join("\n")}\n`;
}

/**
 * Public markdown that an agent reads from the package, relative to the root.
 *
 * @param root - Repository root
 * @returns Sorted paths
 */
export function packedDocPaths(root: string): readonly string[] {
  const paths: string[] = [];
  for (const rel of docsFiles(root)) {
    if (docClass(rel) !== "public" || !rel.endsWith(".md")) continue;
    paths.push(`docs/${rel}`);
  }
  return paths.sort();
}

/**
 * Text files the tarball ships for an agent to read.
 *
 * @param root - Repository root
 * @returns Repo-relative paths
 */
export function packedTextPaths(root: string): readonly string[] {
  const paths = [...packedDocPaths(root), "README.md", "LICENSE"];
  const skills = join(root, "skills");
  if (existsSync(skills)) {
    for (const rel of walkFiles(skills, skills)) paths.push(`skills/${rel}`);
  }
  const schemas = join(root, "schemas");
  if (existsSync(schemas)) {
    for (const rel of walkFiles(schemas, schemas)) {
      if (rel.endsWith(".json")) paths.push(`schemas/${rel}`);
    }
  }
  return paths.sort();
}

/**
 * Rewrites `okmVersion`, and the index title, to the full package version.
 *
 * @param text - Committed markdown
 * @param version - Full `package.json` version
 * @returns The tarball copy
 */
export function stampDocText(text: string, version: string): string {
  if (!/^okmVersion:\s*"[^"]*"/m.test(text)) {
    throw new Error("docs-pack: page has no okmVersion field to stamp");
  }
  const stamped = text.replace(/^okmVersion:\s*"[^"]*"/m, `okmVersion: "${version}"`);
  return stamped.replace(/^OKModel \S+ - agent index$/m, `OKModel ${version} - agent index`);
}

/**
 * Copies public docs aside and stamps `okmVersion` for `npm pack`.
 *
 * @param root - Repository root
 */
export function stampPackedDocs(root: string): void {
  if (existsSync(join(root, PACK_BACKUP))) restorePackedDocs(root);
  const version = packageVersion(root);
  const backup = join(root, PACK_BACKUP);
  for (const rel of packedDocPaths(root)) {
    const from = join(root, rel);
    const to = join(backup, rel);
    mkdirSync(dirname(to), { recursive: true });
    cpSync(from, to);
    writeFileSync(from, stampDocText(readFileSync(from, "utf8"), version));
  }
  writeFileSync(join(backup, "version"), `${version}\n`);
}

/**
 * Puts the committed public docs back. A missing backup is a no-op.
 *
 * @param root - Repository root
 */
export function restorePackedDocs(root: string): void {
  const backup = join(root, PACK_BACKUP);
  if (!existsSync(backup)) return;
  for (const rel of walkFiles(backup, backup)) {
    if (rel === "version") continue;
    const from = join(backup, ...rel.split("/"));
    const to = join(root, ...rel.split("/"));
    mkdirSync(dirname(to), { recursive: true });
    cpSync(from, to);
  }
  rmSync(backup, { recursive: true, force: true });
}

/**
 * Every file under `docs/`, relative to `docs/`, forward slashes, sorted.
 *
 * @param root - Repository root
 * @returns Paths such as `guide.md` and `errors/OKM1012.md`
 */
export function docsFiles(root: string): readonly string[] {
  return walkFiles(join(root, "docs"), join(root, "docs"));
}

/**
 * Every file under `dir`, relative to `base`, forward slashes, sorted.
 *
 * @param dir - Directory to read
 * @param base - Prefix stripped from each path
 * @returns Relative paths. Empty when `dir` is missing
 */
export function walkFiles(dir: string, base: string): readonly string[] {
  if (!existsSync(dir)) return [];
  const files: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...walkFiles(path, base));
      continue;
    }
    if (!entry.isFile()) continue;
    files.push(relative(base, path).split(sep).join("/"));
  }
  return files.sort();
}

/**
 * Handbook path (`/docs/...`) → packed file under `docs/`.
 */
export function sitePathToPackMap(): ReadonlyMap<string, string> {
  const map = new Map<string, string>();
  // Prefer the first pack filename when several pack pages share one site page.
  for (const [pack, siteRel] of Object.entries(SITE_DOC_SOURCES)) {
    const handbook = siteRelToDocsPath(siteRel);
    if (!map.has(handbook)) map.set(handbook, pack);
  }
  return map;
}

function remainingMdxComponent(body: string): string | undefined {
  const prose = body.replace(/```[\s\S]*?```/g, "");
  const match = /<\/?(Callout|Tabs|Tab|Steps|Step|Anatomy|AnatomyPart|AnatomyLine)\b/.exec(prose);
  return match?.[1];
}

/**
 * Inject pack-only `<!-- support -->` / `<!-- steps -->` markers so
 * `docs-capabilities` can refresh them. Site MDX must not carry raw HTML
 * comments (they break the handbook search index).
 */
function injectPackMarkers(packRel: string, body: string): string {
  let text = body;
  const support = PACK_SUPPORT_MARKERS[packRel];
  if (support !== undefined) {
    for (const key of support) {
      if (text.includes(`<!-- support: ${key} -->`)) continue;
      text = `<!-- support: ${key} -->\n\n<!-- /support -->\n\n${text}`;
    }
  }
  if (packRel === "migration-failure.md" && !text.includes("<!-- steps -->")) {
    const heading = "## The step table\n";
    const at = text.indexOf(heading);
    if (at !== -1) {
      const afterHeading = at + heading.length;
      const tableAt = text.indexOf("| Kind |", afterHeading);
      if (tableAt !== -1) {
        const before = text.slice(0, tableAt);
        const rest = text.slice(tableAt);
        const endTable = rest.search(/\n\n(?!\|)/);
        const table = endTable === -1 ? rest : rest.slice(0, endTable);
        const after = endTable === -1 ? "" : rest.slice(endTable);
        text = `${before}<!-- steps -->\n${table.trimEnd()}\n<!-- /steps -->${after}`;
      }
    }
  }
  return text;
}

/** Support keys the capabilities check expects on specific pack pages. */
const PACK_SUPPORT_MARKERS: Readonly<Record<string, readonly string[]>> = {
  "compatibility.md": ["type.uuidv7"],
  "migration-failure.md": ["steps.resumable"],
  "testing.md": ["tooling.testing"],
  "migrate-check.md": ["tooling.scratchReplay"],
  "observer-events.md": [
    "writeObserver.unit",
    "writeObserver.keys",
    "writeObserver.rowCount",
    "queryObserver.timing",
  ],
};

/**
 * Generate packed docs and throw when the write fails.
 *
 * Tests that read a generated public page call this first so a clean
 * checkout (no gitignored `docs/*.md`) still works.
 *
 * @param root - Repository root
 */
export function ensurePackedDocs(root: string): void {
  const problems = generatePackedDocs(root);
  if (problems.length > 0) {
    throw new Error(problems.join("\n"));
  }
}

/**
 * Generate every public package page that is not hand-kept.
 *
 * Writes into `docs/` (gitignored for generated paths). Safe to call before
 * `docs:check`, tests, or `prepack`.
 *
 * @param root - Repository root
 * @returns Problem lines (empty on success)
 */
export function generatePackedDocs(root: string): readonly string[] {
  const problems: string[] = [];
  const version = packageVersion(root);
  const train = committedDocVersion(version);
  const linkMap = sitePathToPackMap();

  for (const [packRel, siteRel] of Object.entries(SITE_DOC_SOURCES)) {
    const sitePath = join(root, "site/content/docs", siteRel);
    if (!existsSync(sitePath)) {
      problems.push(`docs-pack: missing site page ${siteRel} for ${packRel}`);
      continue;
    }
    const raw = readFileSync(sitePath, "utf8");
    let body = mdxToPackBody(raw);
    const rewritten = rewriteHandbookLinks(body, packRel, linkMap);
    body = rewritten.text;
    // Leftover `/docs/` paths become absolute handbook URLs; record none as hard failures
    // unless a rewrite left a bare `/docs` link (should not happen).
    for (const url of rewritten.unrewritten) {
      if (url.startsWith("/docs") && !body.includes(`https://okm.omqkhafi.dev${url}`)) {
        problems.push(`docs-pack: ${packRel} left unrewritten site link ${url}`);
      }
    }
    if (remainingMdxComponent(body) !== undefined) {
      problems.push(
        `docs-pack: ${packRel} still contains an MDX component tag (${remainingMdxComponent(body)})`,
      );
    }
    body = injectPackMarkers(packRel, body);
    const meta = DOC_META[packRel] ?? { since: "0.10", dialects: ["postgres"] };
    const codes = codesInText(body);
    writeFileSync(join(root, "docs", packRel), packFrontMatter(train, meta, codes) + body);
  }

  writeCapabilityDocs(root);
  writeFileSync(join(root, "docs/index.md"), renderDocsIndex(version));
  writeExtensionCompatibility(root, train);

  const errorsDir = join(root, "docs/errors");
  mkdirSync(errorsDir, { recursive: true });
  const expected = new Set(ERROR_DOCS.map((doc) => doc.code));
  for (const doc of ERROR_DOCS) {
    writeFileSync(join(errorsDir, `${doc.code}.md`), renderErrorPage(doc, pageExample(doc.code)));
  }
  if (existsSync(errorsDir)) {
    for (const name of readdirSync(errorsDir)) {
      if (!/^OKM\d{4}\.md$/.test(name)) continue;
      const code = name.slice(0, -".md".length);
      if (!expected.has(code as (typeof ERROR_DOCS)[number]["code"])) {
        rmSync(join(errorsDir, name));
      }
    }
  }

  for (const packRel of Object.keys(SITE_DOC_SOURCES)) {
    if (!existsSync(join(root, "docs", packRel))) {
      problems.push(`docs-pack: generate did not write ${packRel}`);
    }
  }
  for (const code of expected) {
    if (!existsSync(join(errorsDir, `${code}.md`))) {
      problems.push(`docs-pack: generate did not write errors/${code}.md`);
    }
  }
  return problems;
}

/**
 * Verify the generated tree: site map coverage, registry pages, no bare site links.
 *
 * @param root - Repository root
 * @returns Problem lines
 */
export function generatedDocsProblems(root: string): readonly string[] {
  const problems: string[] = [];
  const linkMap = sitePathToPackMap();
  const siteFiles = new Set(
    walkFiles(join(root, "site/content/docs"), join(root, "site/content/docs")).filter((rel) =>
      rel.endsWith(".mdx"),
    ),
  );

  for (const [packRel, siteRel] of Object.entries(SITE_DOC_SOURCES)) {
    if (!siteFiles.has(siteRel)) {
      problems.push(`docs-pack: ${packRel} maps to missing site page ${siteRel}`);
    }
    const path = join(root, "docs", packRel);
    if (!existsSync(path)) {
      problems.push(`docs-pack: generated page ${packRel} is missing; run generate`);
      continue;
    }
    const text = readFileSync(path, "utf8");
    for (const match of text.matchAll(/\]\(\s*(\/docs[^)\s]*)\s*\)/g)) {
      const url = match[1];
      if (url !== undefined) problems.push(`docs-pack: ${packRel} still has site link ${url}`);
    }
    for (const match of text.matchAll(/\]\(\s*([^)\s]+\.md(?:#[^)\s]*)?)\s*\)/g)) {
      const target = match[1];
      if (target === undefined || target.startsWith("http")) continue;
      const resolved = join(root, "docs", dirname(packRel), target.split("#")[0] ?? target);
      if (!existsSync(resolved)) {
        problems.push(`docs-pack: ${packRel} links to ${target}, which is not in the tarball tree`);
      }
    }
  }

  for (const doc of ERROR_DOCS) {
    const path = join(root, "docs/errors", `${doc.code}.md`);
    if (!existsSync(path)) {
      problems.push(`docs-pack: missing generated errors/${doc.code}.md`);
    }
  }

  for (const packRel of PUBLIC_DOCS) {
    if ((HAND_KEPT_DOCS as readonly string[]).includes(packRel)) continue;
    if ((CODE_DOC_SOURCES as readonly string[]).includes(packRel)) continue;
    if (!(packRel in SITE_DOC_SOURCES)) {
      problems.push(`docs-pack: public page ${packRel} has no site or code source`);
    }
  }

  // Every site-sourced pack page maps to exactly one site page (enforced by the record type).
  const seenSite = new Map<string, string>();
  for (const [packRel, siteRel] of Object.entries(SITE_DOC_SOURCES)) {
    const previous = seenSite.get(siteRel);
    // Multiple pack files may share one site page (protection + roles).
    if (previous !== undefined && previous !== packRel) {
      // allowed
    }
    seenSite.set(siteRel, packRel);
    void linkMap;
  }

  return problems;
}

function siteRelToDocsPath(siteRel: string): string {
  const withoutExt = siteRel.replace(/\.mdx$/, "");
  if (withoutExt === "index") return "/docs";
  if (withoutExt.endsWith("/index")) {
    return `/docs/${withoutExt.slice(0, -"/index".length)}`;
  }
  return `/docs/${withoutExt}`;
}

function packFrontMatter(
  train: string,
  meta: { readonly since: string; readonly dialects: readonly string[] },
  codes: readonly string[],
): string {
  const dialects = meta.dialects.join(", ");
  const codesField = codes.length === 0 ? "codes: []" : `codes: [${codes.join(", ")}]`;
  return `---\nokmVersion: "${train}"\nsince: "${meta.since}"\ndialects: [${dialects}]\n${codesField}\n---\n`;
}

function writeExtensionCompatibility(root: string, train: string): void {
  // Keep the generator's table body; wrap with pack front matter.
  const { compatibilityDoc } = requireExtGenerate();
  const body = compatibilityDoc().replace(/^\n+/, "");
  const meta = DOC_META["extension-compatibility.md"] ?? { since: "0.9", dialects: ["postgres"] };
  const text =
    packFrontMatter(train, meta, []) + (body.startsWith("#") ? body : stripYamlFrontmatter(body));
  writeFileSync(
    join(root, "docs/extension-compatibility.md"),
    text.endsWith("\n") ? text : `${text}\n`,
  );
}

function requireExtGenerate(): { compatibilityDoc: () => string } {
  // Lazy require keeps docs-pack importable without evaluating ext packs at module load.
  // The function is file-local in ext-generate; re-implement the small table from versions.
  const versionsPath = join(repoRoot(), "src/dialects/pg/ext/versions.ts");
  const source = readFileSync(versionsPath, "utf8");
  const packs: { name: string; versions: Record<string, string> }[] = [];
  const block = /"([^"]+)":\s*\{\s*([\s\S]*?)\n\s*\}/g;
  let match: RegExpExecArray | null;
  while ((match = block.exec(source)) !== null) {
    const name = match[1];
    const body = match[2] ?? "";
    if (name === undefined) continue;
    const versions: Record<string, string> = {};
    for (const row of body.matchAll(/"(\d+)":\s*"([^"]+)"/g)) {
      const major = row[1];
      const ver = row[2];
      if (major !== undefined && ver !== undefined) versions[major] = ver;
    }
    if (Object.keys(versions).length > 0) packs.push({ name, versions });
  }
  const majors = ["15", "16", "17", "18"];
  const header = majors.map((m) => `Postgres ${m}`).join(" | ");
  const rule = majors.map(() => "---").join(" | ");
  const rows = packs
    .map((pack) => {
      const cells = majors.map((major) => pack.versions[major] ?? "").join(" | ");
      return `| \`${pack.name}\` | ${cells} |`;
    })
    .join("\n");
  return {
    compatibilityDoc: () => `# Extension compatibility

Generated by \`scripts/ext-generate.ts\` from the contrib control files on the \`REL_15_STABLE\` through \`REL_18_STABLE\` branches. The number is \`default_version\`. The drift check compares it with the connected server.

\`vector\` is not in this table. The CI images are official \`postgres\` images, which do not ship pgvector (D281).

| Extension | ${header} |
| --- | ${rule} |
${rows}
`,
  };
}

function packageVersion(root: string): string {
  const parsed: unknown = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));
  if (typeof parsed !== "object" || parsed === null || !("version" in parsed)) {
    throw new Error("docs-pack: package.json has no version");
  }
  const version = (parsed as { version?: unknown }).version;
  if (typeof version !== "string" || version.length === 0) {
    throw new Error("docs-pack: package.json version is not a string");
  }
  return version;
}

if (import.meta.main) {
  const root = repoRoot();
  const [mode] = process.argv.slice(2);
  if (mode === "stamp") {
    const gen = generatePackedDocs(root);
    if (gen.length > 0) exitOnProblems(gen);
    stampPackedDocs(root);
  } else if (mode === "restore") {
    restorePackedDocs(root);
  } else if (mode === "generate") {
    const problems = generatePackedDocs(root);
    if (problems.length > 0) exitOnProblems(problems);
    console.log("docs-pack: generated public package docs");
  } else if (mode === "--write-ignore" || mode === undefined) {
    if (mode === "--write-ignore") {
      writeFileSync(join(root, NPM_IGNORE), npmIgnoreText());
      console.log(`docs-pack: wrote ${NPM_IGNORE}`);
    }
    const problems = classificationProblems(root);
    if (problems.length > 0) exitOnProblems(problems);
    if (mode !== "--write-ignore") {
      const ignorePath = join(root, NPM_IGNORE);
      const ignore = existsSync(ignorePath) ? readFileSync(ignorePath, "utf8") : "";
      if (ignore !== npmIgnoreText()) {
        exitOnProblems([
          "docs-pack: docs/.npmignore does not match the internal list. Run with --write-ignore.",
        ]);
      }
    }
  } else {
    exitOnProblems(["docs-pack: usage is generate, stamp, restore, or --write-ignore"]);
  }
}
